+#[test]
+fn a_counts_on_through_180_and_360_never_back_through_0() {
+    let out = run(&wide(), &wrap_stream(361.0));
+    let a: Vec<f64> = lines(&out.program)
+        .iter()
+        .flat_map(|l| l.split(' '))
+        .filter_map(|w| w.strip_prefix('A').and_then(|v| v.parse().ok()))
+        .collect();
